import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Inspect{public static void main(String[]args)throws Exception{int count=0;Set<String>names=Set.of("Vision12","NvgFinalPass13","LaserType36","Laser32","ClientAim14","PlayerAim14");for(String path:args)try(ZipFile z=new ZipFile(path)){for(var e:Collections.list(z.entries())){String n=e.getName();if(n.endsWith(".class")&&names.contains(n.substring(n.lastIndexOf('/')+1,n.length()-6))){ClassNode c=new ClassNode();new ClassReader(z.getInputStream(e).readAllBytes()).accept(c,0);for(var m:c.methods)if((m.access&(Opcodes.ACC_ABSTRACT|Opcodes.ACC_NATIVE))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);count++;}}}if(count!=6)throw new AssertionError(count);System.out.println("FINAL_NEW_HOOK_HELPER_BYTECODE_CHECKS="+count);}}
